        if ch == '~':
            nxt = line[i+1] if i+1 < 80 else '?'
            c[0x80 + ord(nxt) - 0x40 if ord(nxt) < 0x60 else 0xA0 + ord(nxt) - 0x20] += 1
        elif ch == '^':
            c[0x7f] += 1
        else:
            c[ord(ch)] += 1
for k in sorted(c): print(hex(k), c[k])
print(len(c))
EOF"}

