        elif cmd == 'G': self.c = (p[0] if p and p[0] else 1)-1
        elif cmd == 'd': self.r = (p[0] if p and p[0] else 1)-1
        elif cmd == 'A': self.r = max(0, self.r - (p[0] if p and p[0] else 1))
        elif cmd == 'B': self.r = min(self.rows-1, self.r + (p[0] if p and p[0] else 1))
        elif cmd == 'C': self.c = min(self.cols-1, self.c + (p[0] if p and p[0] else 1))
        elif cmd == 'D': self.c = max(0, self.c - (p[0] if p and p[0] else 1))
        elif cmd == 'J':
            if not p or p[0] == 0:
                for cc in range(self.c, self.cols): self.cells[self.r][cc] = (b' ', '', False)
                for rr in range(self.r+1, self.rows):
                    for cc in range(self.cols): self.cells[rr][cc] = (b' ', '', False)
            elif p[0] == 2:
                for rr in range(self.rows):
                    for cc in range(self.cols): self.cells[rr][cc] = (b' ', '', False)
        elif cmd == 'K':
