                for cc in range(self.c, self.cols): self.cells[self.r][cc] = (b' ', '', False)
            elif p[0] == 1:
                for cc in range(0, self.c+1): self.cells[self.r][cc] = (b' ', '', False)
            elif p[0] == 2:
                for cc in range(self.cols): self.cells[self.r][cc] = (b' ', '', False)
