                    else: self.sgr += x
        elif cmd == 'r': pass
        elif cmd == 'l' or cmd == 'h': pass
    def dump(self, attrs=False):
        out = []
        for row in self.cells:
            if attrs:
                out.append(' '.join(('%s%s%s' % (c[0].decode('latin1') if c[0] >= b' ' and c[0] < b'\x7f' else '\\x%02x' % c[0][0], ('/'+c[1]) if c[1] else '', '*' if c[2] else '')) for c in row))
