import os, pty, sys, time, select, fcntl, termios, struct, signal
sys.path.insert(0, '/tmp/t')
from term import Term
def frames(cmd, keys=(), duration=1.0, rows=24, cols=80, env=None, gap=0.03):
    pid, fd = pty.fork()
    if pid == 0:
        if env: os.environ.update(env)
        os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    chunks = []
    start = time.time(); keys = list(keys)
    last = None
    while True:
        now = time.time()
        if keys and now - start >= keys[0][0]:
            os.write(fd, keys[0][1]); keys.pop(0)
        r,_,_ = select.select([fd], [], [], 0.005)
        if r:
            try: data = os.read(fd, 65536)
            except OSError: break
            if not data: break
            chunks.append((time.time(), data))
        if now - start > duration: break
    try: os.kill(pid, signal.SIGKILL)
    except Exception: pass
    os.waitpid(pid, 0)
    # group
    groups = []
    for t, d in chunks:
        if groups and t - groups[-1][1] < gap:
            groups[-1][2] += d; groups[-1][1] = t
        else:
