def run_resize(cmd, resize_at, newsize, duration=1.5, rows=24, cols=80, env=None, keys=()):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ.update(env or {}); os.environ.pop('LC_CTYPE', None); os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
