        if not resized and now - start >= resize_at:
            fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', newsize[0], newsize[1], 0, 0))
            os.kill(pid, signal.SIGWINCH); resized = True; marker = len(out)
