import os, pty, sys, time, select, fcntl, termios, struct, signal
def chunks(cmd, keys, duration=2.0, env=None, sig=None):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ.update(env or {}); os.environ.pop('LC_CTYPE', None); os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 24, 80, 0, 0))
    start = time.time(); out = []; keys = list(keys); data = b''
    while time.time() - start < duration:
        now = time.time()
        if keys and now - start >= keys[0][0]:
            if isinstance(keys[0][1], int): os.kill(pid, keys[0][1])
            else: os.write(fd, keys[0][1])
            keys.pop(0)
        r,_,_ = select.select([fd], [], [], 0.005)
        if r:
            try: d = os.read(fd, 65536)
            except OSError: break
            out.append((round(time.time()-start, 2), len(d))); data += d
    try: os.kill(pid, signal.SIGKILL)
    except: pass
