/*
 * cmatrix - a terminal "falling code" screensaver, reimplemented from
 * observed behaviour of the reference binary.
 *
 * Build: see compile.sh (requires ncursesw).
 */
#define _XOPEN_SOURCE_EXTENDED 1
#define _GNU_SOURCE 1

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <locale.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <wchar.h>
#include <sys/ioctl.h>
#include <termios.h>

#include <ncursesw/curses.h>

#include "version.h"

/* A single cell of the falling-code matrix. */
typedef struct {
    int val;        /* character code, ' ' for an empty cell, -1 for "nothing", 0/1 are special markers */
    int is_head;    /* non-zero if this cell is the leading (white) character of a stream */
} cell_t;

/* Global state (shared with the signal handlers). */
static cell_t **matrix = NULL;
static int *length = NULL;      /* per column: length of the current stream */
static int *spaces = NULL;      /* per column: blank cells to emit before the next stream */
static int *updates = NULL;     /* per column: speed class used by asynchronous mode */

static int console = 0;         /* -l */
static int xwindow = 0;         /* -x */
static int lock = 0;            /* -L */

static void finish(void);
static void var_init(void);
static void resize_screen(void);

/* Print a message to stderr after shutting curses down, then exit. */
static void c_die(const char *fmt, ...)
{
    va_list ap;

    curs_set(1);
    clear();
    refresh();
    endwin();

    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);

    exit(0);
}

static void usage(void)
{
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void version(void)
{
    printf(" CMatrix version %s (compiled %s, %s)\n", CMATRIX_VERSION, CMATRIX_BUILD_TIME, CMATRIX_BUILD_DATE);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

static void *nmalloc(size_t howmuch)
{
    void *r = malloc(howmuch);
    if (r == NULL) {
        c_die("CMatrix: malloc() failed, out of memory.\n");
    }
    return r;
}

/* (Re)allocate and initialise the matrix for the current LINES/COLS. */
static void var_init(void)
{
    int i, j;

    if (matrix != NULL) {
        free(matrix[0]);
        free(matrix);
    }
    matrix = nmalloc(sizeof(cell_t *) * (LINES + 1));
    matrix[0] = nmalloc(sizeof(cell_t) * (LINES + 1) * COLS);
    for (i = 1; i <= LINES; i++) {
        matrix[i] = matrix[i - 1] + COLS;
    }

    if (length != NULL) free(length);
    length = nmalloc(COLS * sizeof(int));
    if (spaces != NULL) free(spaces);
    spaces = nmalloc(COLS * sizeof(int));
    if (updates != NULL) free(updates);
    updates = nmalloc(COLS * sizeof(int));

    for (i = 0; i <= LINES; i++) {
        for (j = 0; j <= COLS - 1; j++) {
            matrix[i][j].val = -1;
            matrix[i][j].is_head = 0;
        }
    }
    for (j = 0; j <= COLS - 1; j += 2) {
        spaces[j] = (int) rand() % LINES + 1;
        length[j] = (int) rand() % (LINES - 3) + 3;
        matrix[1][j].val = ' ';
        updates[j] = (int) rand() % 3 + 1;
    }
}

static void sighandler(int s)
{
    switch (s) {
    case SIGINT:
    case SIGQUIT:
    case SIGTSTP:
        finish();
        break;
    case SIGWINCH:
        resize_screen();
        break;
    }
}

/* Pick up the new terminal size and start over with a fresh matrix. */
static void resize_screen(void)
{
    char *tty;
    int fd;
    struct winsize win;

    tty = ttyname(0);
    if (!tty) {
        return;
    }
    fd = open(tty, O_RDWR);
    if (fd == -1) {
        return;
    }
    if (ioctl(fd, TIOCGWINSZ, &win) == -1) {
        close(fd);
        return;
    }
    close(fd);

    COLS = win.ws_col;
    LINES = win.ws_row;

    if (LINES < 10) {
        LINES = 10;
    }
    if (COLS < 10) {
        COLS = 10;
    }

    var_init();
    clear();
    refresh();
}

static void finish(void)
{
    curs_set(1);
    clear();
    refresh();
    endwin();
    exit(0);
}

int main(int argc, char *argv[])
{
    int i, j, count = 0, screensaver = 0, asynch = 0, bold = 0;
    int force = 0, firstcoldone = 0, oldstyle = 0, random = 0;
    int update = 4, highnum = 0, mcolor = COLOR_GREEN, rainbow = 0, lambda = 0;
