    }

    while (1) {
        count++;
        if (count > 4) {
            count = 1;
        }

        if ((keypress = wgetch(stdscr)) != ERR) {
            if (screensaver == 1) {
                finish();
            } else {
                switch (keypress) {
                case 'q':
                    if (lock != 1) {
                        finish();
                    }
                    break;
                case 'a':
                    asynch = 1 - asynch;
                    break;
                case 'b':
                    bold = 1;
                    break;
                case 'B':
                    bold = 2;
                    break;
                case 'L':
                    lock = 1;
                    break;
                case 'n':
                    bold = 0;
                    break;
                case '0':
                case '1':
                case '2':
                case '3':
                case '4':
                case '5':
                case '6':
                case '7':
                case '8':
                case '9':
                    update = keypress - '0';
                    break;
                case '!':
                    mcolor = COLOR_RED;
                    rainbow = 0;
                    break;
                case '@':
                    mcolor = COLOR_GREEN;
                    rainbow = 0;
                    break;
                case '#':
                    mcolor = COLOR_YELLOW;
                    rainbow = 0;
                    break;
                case '$':
                    mcolor = COLOR_BLUE;
                    rainbow = 0;
                    break;
                case '%':
                    mcolor = COLOR_MAGENTA;
                    rainbow = 0;
                    break;
                case 'r':
                    rainbow = 1;
                    break;
                case 'm':
                    lambda = !lambda;
                    break;
                case '^':
                    mcolor = COLOR_CYAN;
                    rainbow = 0;
                    break;
                case '&':
                    mcolor = COLOR_WHITE;
                    rainbow = 0;
                    break;
                case 'p':
                case 'P':
                    pause = (pause == 0) ? 1 : 0;
                    break;
                }
            }
        }

        for (j = 0; j <= COLS - 1; j += 2) {
            if ((count > updates[j] || asynch == 0) && pause == 0) {
                if (oldstyle) {
                    /* Old style: shift the whole column down one cell and
                     * decide what enters at the top. */
                    for (i = LINES; i >= 1; i--) {
                        matrix[i][j].val = matrix[i - 1][j].val;
                    }
                    random = (int) rand() % (randnum + 8) + randmin;

                    if (matrix[1][j].val == 0) {
                        matrix[0][j].val = 1;
                    } else if (matrix[1][j].val == ' ' || matrix[1][j].val == -1) {
                        if (spaces[j] > 0) {
                            matrix[0][j].val = ' ';
                            spaces[j]--;
                        } else {
                            /* One in three streams gets a white head. */
                            if (((int) rand() % 3) == 1) {
                                matrix[0][j].val = 0;
                            } else {
                                matrix[0][j].val = (int) rand() % randnum + randmin;
                            }
                            spaces[j] = (int) rand() % LINES + 1;
                        }
                    } else if (random > highnum && matrix[1][j].val != 1) {
                        matrix[0][j].val = ' ';
                    } else {
                        matrix[0][j].val = (int) rand() % randnum + randmin;
                    }
                } else {
                    /* New style scrolling (default). */
                    if (matrix[0][j].val == -1 && matrix[1][j].val == ' ' && spaces[j] > 0) {
                        spaces[j]--;
                    } else if (matrix[0][j].val == -1 && matrix[1][j].val == ' ') {
                        length[j] = (int) rand() % (LINES - 3) + 3;
                        matrix[0][j].val = (int) rand() % randnum + randmin;
                        spaces[j] = (int) rand() % LINES + 1;
                    }
                    i = 0;
                    y = 0;
                    firstcoldone = 0;
                    while (i <= LINES) {
                        /* Skip over spaces */
                        while (i <= LINES && (matrix[i][j].val == ' ' || matrix[i][j].val == -1)) {
                            i++;
                        }
                        if (i > LINES) {
                            break;
                        }
                        /* Go to the head of this stream */
                        z = i;
                        y = 0;
                        while (i <= LINES && (matrix[i][j].val != ' ' && matrix[i][j].val != -1)) {
                            matrix[i][j].is_head = 0;
                            if (changes) {
                                if (rand() % 8 == 0) {
                                    matrix[i][j].val = (int) rand() % randnum + randmin;
                                }
                            }
                            i++;
                            y++;
                        }
                        if (i > LINES) {
                            matrix[z][j].val = ' ';
                            continue;
                        }
                        matrix[i][j].val = (int) rand() % randnum + randmin;
                        matrix[i][j].is_head = 1;

                        /* Once the stream reached its full length (or this is
                         * not the first stream in the column) start eating
                         * its tail so that it moves down. */
                        if (y > length[j] || firstcoldone) {
                            matrix[z][j].val = ' ';
                            matrix[0][j].val = -1;
                        }
                        firstcoldone = 1;
                        i++;
                    }
                }
            }

            /* Display this column */
            for (i = 1; i <= LINES; ++i) {
                move(i - 1, j);
                if (matrix[i][j].val == 0 || (matrix[i][j].is_head && !rainbow)) {
                    if (console || xwindow) {
                        attron(A_ALTCHARSET);
                    }
                    attron(COLOR_PAIR(COLOR_WHITE));
                    if (bold) {
                        attron(A_BOLD);
                    }
                    if (matrix[i][j].val == 0) {
                        if (console || xwindow) {
                            addch(183);
                        } else {
                            addch('&');
                        }
                    } else {
                        addch(matrix[i][j].val);
                    }
                    attroff(COLOR_PAIR(COLOR_WHITE));
                    if (bold) {
                        attroff(A_BOLD);
                    }
                    if (console || xwindow) {
                        attroff(A_ALTCHARSET);
                    }
                } else {
                    if (rainbow) {
                        int randomColor = rand() % 6;
                        switch (randomColor) {
                        case 0:
                            mcolor = COLOR_GREEN;
                            break;
                        case 1:
                            mcolor = COLOR_BLUE;
                            break;
                        case 2:
                            mcolor = COLOR_BLACK;
                            break;
                        case 3:
                            mcolor = COLOR_YELLOW;
                            break;
                        case 4:
                            mcolor = COLOR_CYAN;
                            break;
                        case 5:
                            mcolor = COLOR_MAGENTA;
                            break;
                        }
                    }
                    attron(COLOR_PAIR(mcolor));
                    if (matrix[i][j].val == 1) {
                        if (bold) {
                            attron(A_BOLD);
                        }
                        addch('|');
                        if (bold) {
                            attroff(A_BOLD);
                        }
                    } else {
                        if (console || xwindow) {
                            attron(A_ALTCHARSET);
                        }
                        if (bold == 2 || (bold == 1 && matrix[i][j].val % 2 == 0)) {
                            attron(A_BOLD);
                        }
                        if (matrix[i][j].val == -1) {
                            addch(' ');
                        } else if (lambda && matrix[i][j].val != ' ') {
                            addstr("\xce\xbb"); /* "λ" */
                        } else {
                            wchar_t wc[2];
                            wc[0] = (wchar_t) matrix[i][j].val;
                            wc[1] = L'\0';
                            addwstr(wc);
                        }
                        if (bold == 2 || (bold == 1 && matrix[i][j].val % 2 == 0)) {
                            attroff(A_BOLD);
                        }
                        if (console || xwindow) {
                            attroff(A_ALTCHARSET);
                        }
                    }
                    attroff(COLOR_PAIR(mcolor));
                }
            }
        }

        /* Centered message, boxed by a one-cell blank border. */
        if (msg[0] != '\0') {
            int msg_x = COLS / 2 - (int) strlen(msg) / 2;
            int msg_y = LINES / 2;
            int k;

            attron(COLOR_PAIR(COLOR_WHITE));
            attroff(COLOR_PAIR(COLOR_WHITE));
            move(msg_y - 1, msg_x - 2);
            for (k = 0; k < (int) strlen(msg) + 4; k++) {
                addch(' ');
            }
            move(msg_y, msg_x - 2);
            addch(' ');
            addch(' ');
            addstr(msg);
            addch(' ');
            addch(' ');
            move(msg_y + 1, msg_x - 2);
            for (k = 0; k < (int) strlen(msg) + 4; k++) {
                addch(' ');
            }
        }

        napms(update * 10);
    }
    finish();
    return 0;
}
