/*
 * cmatrix - a terminal "falling code" screensaver, reimplemented from
 * observed behaviour of the reference binary.
 *
 * Build: see compile.sh (requires ncursesw).
 */
#define _XOPEN_SOURCE_EXTENDED 1
#define _GNU_SOURCE 1

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <locale.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <wchar.h>
#include <sys/ioctl.h>
#include <termios.h>

#include <ncursesw/curses.h>

#include "version.h"

/* A single cell of the falling-code matrix. */
typedef struct {
    int val;        /* character code, ' ' for an empty cell, -1 for "nothing", 0/1 are special markers */
    int is_head;    /* non-zero if this cell is the leading (white) character of a stream */
} cell_t;

/* Global state (shared with the signal handlers). */
static cell_t **matrix = NULL;
static int *length = NULL;      /* per column: length of the current stream */
static int *spaces = NULL;      /* per column: blank cells to emit before the next stream */
static int *updates = NULL;     /* per column: speed class used by asynchronous mode */

static int console = 0;         /* -l */
static int xwindow = 0;         /* -x */
static int lock = 0;            /* -L */

static void finish(void);
static void var_init(void);
static void resize_screen(void);

/* Print a message to stderr after shutting curses down, then exit. */
static void c_die(const char *fmt, ...)
{
    va_list ap;

    curs_set(1);
    clear();
    refresh();
    endwin();

    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);

    exit(0);
}

static void usage(void)
{
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void version(void)
{
    printf(" CMatrix version %s (compiled %s, %s)\n", CMATRIX_VERSION, CMATRIX_BUILD_TIME, CMATRIX_BUILD_DATE);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

static void *nmalloc(size_t howmuch)
{
    void *r = malloc(howmuch);
    if (r == NULL) {
        c_die("CMatrix: malloc() failed, out of memory.\n");
    }
    return r;
}

/* (Re)allocate and initialise the matrix for the current LINES/COLS. */
static void var_init(void)
{
    int i, j;

    if (matrix != NULL) {
        free(matrix[0]);
        free(matrix);
    }
    matrix = nmalloc(sizeof(cell_t *) * (LINES + 1));
    matrix[0] = nmalloc(sizeof(cell_t) * (LINES + 1) * COLS);
    for (i = 1; i <= LINES; i++) {
        matrix[i] = matrix[i - 1] + COLS;
    }

    if (length != NULL) free(length);
    length = nmalloc(COLS * sizeof(int));
    if (spaces != NULL) free(spaces);
    spaces = nmalloc(COLS * sizeof(int));
    if (updates != NULL) free(updates);
    updates = nmalloc(COLS * sizeof(int));

    for (i = 0; i <= LINES; i++) {
        for (j = 0; j <= COLS - 1; j++) {
            matrix[i][j].val = -1;
            matrix[i][j].is_head = 0;
        }
    }
    for (j = 0; j <= COLS - 1; j += 2) {
        spaces[j] = (int) rand() % LINES + 1;
        length[j] = (int) rand() % (LINES - 3) + 3;
        matrix[1][j].val = ' ';
        updates[j] = (int) rand() % 3 + 1;
    }
}

static void sighandler(int s)
{
    switch (s) {
    case SIGINT:
    case SIGQUIT:
    case SIGTSTP:
        finish();
        break;
    case SIGWINCH:
        resize_screen();
        break;
    }
}

/* Pick up the new terminal size and start over with a fresh matrix. */
static void resize_screen(void)
{
    char *tty;
    int fd;
    struct winsize win;

    tty = ttyname(0);
    if (!tty) {
        return;
    }
    fd = open(tty, O_RDWR);
    if (fd == -1) {
        return;
    }
    if (ioctl(fd, TIOCGWINSZ, &win) == -1) {
        close(fd);
        return;
    }
    close(fd);

    COLS = win.ws_col;
    LINES = win.ws_row;

    if (LINES < 10) {
        LINES = 10;
    }
    if (COLS < 10) {
        COLS = 10;
    }

    var_init();
    clear();
    refresh();
}

static void finish(void)
{
    curs_set(1);
    clear();
    refresh();
    endwin();
    exit(0);
}

int main(int argc, char *argv[])
{
    int i, j, count = 0, screensaver = 0, asynch = 0, bold = 0;
    int force = 0, firstcoldone = 0, oldstyle = 0, random = 0;
    int update = 4, highnum = 0, mcolor = COLOR_GREEN, rainbow = 0, lambda = 0;
    int randnum = 0, randmin = 0, pause = 0, classic = 0, changes = 0;
    int optchr, keypress;
    int y, z;
    char *msg = "";
    char *tty = NULL;
    FILE *ttyfile = NULL;

    setlocale(LC_ALL, "");

    /* Suppress getopt's own diagnostics; unknown options just print the usage. */
    opterr = 0;
    while ((optchr = getopt(argc, argv, "abBcfhlLnrosmxkVM:u:C:t:")) != EOF) {
        switch (optchr) {
        case 's':
            screensaver = 1;
            break;
        case 'a':
            asynch = 1;
            break;
        case 'b':
            if (bold != 2) {
                bold = 1;
            }
            break;
        case 'B':
            bold = 2;
            break;
        case 'C':
            if (!strcasecmp(optarg, "green")) {
                mcolor = COLOR_GREEN;
            } else if (!strcasecmp(optarg, "red")) {
                mcolor = COLOR_RED;
            } else if (!strcasecmp(optarg, "blue")) {
                mcolor = COLOR_BLUE;
            } else if (!strcasecmp(optarg, "white")) {
                mcolor = COLOR_WHITE;
            } else if (!strcasecmp(optarg, "yellow")) {
                mcolor = COLOR_YELLOW;
            } else if (!strcasecmp(optarg, "cyan")) {
                mcolor = COLOR_CYAN;
            } else if (!strcasecmp(optarg, "magenta")) {
                mcolor = COLOR_MAGENTA;
            } else if (!strcasecmp(optarg, "black")) {
                mcolor = COLOR_BLACK;
            } else {
                c_die(" Invalid color selection\n Valid "
                      "colors are green, red, blue, "
                      "white, yellow, cyan, magenta "
                      "and black.\n");
            }
            break;
        case 'c':
            classic = 1;
            break;
        case 'f':
            force = 1;
            break;
        case 'l':
            console = 1;
            break;
        case 'L':
            lock = 1;
            if (strlen(msg) == 0) {
                msg = "Computer locked.";
            }
            break;
        case 'M':
            msg = strdup(optarg);
            break;
        case 'n':
            bold = -1;
            break;
        case 'h':
        case '?':
            usage();
            exit(0);
        case 'o':
            oldstyle = 1;
            break;
        case 'u':
            update = atoi(optarg);
            break;
        case 'x':
            xwindow = 1;
            break;
        case 'V':
            version();
            exit(0);
        case 'r':
            rainbow = 1;
            break;
        case 'm':
            lambda = 1;
            break;
        case 'k':
            changes = 1;
            break;
        case 't':
            tty = optarg;
            break;
        }
    }

    /* Clamp the update delay; anything outside 0..10 falls back to the default. */
    if (update < 0 || update > 10) {
        update = 4;
    }

    if (force && strcmp("linux", getenv("TERM") ? getenv("TERM") : "")) {
        /* Portable way to force the TERM variable to "linux". */
        setenv("TERM", "linux", 1);
    }

    if (tty) {
        ttyfile = fopen(tty, "r+");
        if (!ttyfile) {
            fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n", tty, strerror(errno));
            exit(1);
        }
        newterm(NULL, ttyfile, ttyfile);
    } else {
        initscr();
    }
    savetty();
    nonl();
    cbreak();
    noecho();
    timeout(0);
    leaveok(stdscr, TRUE);
    curs_set(0);
    signal(SIGINT, sighandler);
    signal(SIGQUIT, sighandler);
    signal(SIGWINCH, sighandler);
    signal(SIGTSTP, sighandler);

    if (console) {
        /* Neither "setfont" nor "consolechars" support is compiled in. */
        c_die(" Unable to use both \"setfont\" and \"consolechars\".\n");
    }

    if (console || xwindow) {
        randnum = 51;
        randmin = 166;
        highnum = 217;
    } else if (classic) {
        /* Half-width katakana block, as seen in the original matrix. */
        randmin = 0xFF66;
        highnum = 0xFF9D;
        randnum = highnum - randmin;
    } else {
        randmin = 33;
        highnum = 123;
        randnum = highnum - randmin;
    }

    srand(time(NULL));
    var_init();

    if (has_colors()) {
        start_color();
        /* Add in colors, if available */
        if (use_default_colors() != ERR) {
            init_pair(COLOR_BLACK, -1, -1);
            init_pair(COLOR_GREEN, COLOR_GREEN, -1);
            init_pair(COLOR_WHITE, COLOR_WHITE, -1);
            init_pair(COLOR_RED, COLOR_RED, -1);
            init_pair(COLOR_CYAN, COLOR_CYAN, -1);
            init_pair(COLOR_MAGENTA, COLOR_MAGENTA, -1);
            init_pair(COLOR_BLUE, COLOR_BLUE, -1);
            init_pair(COLOR_YELLOW, COLOR_YELLOW, -1);
        } else {
            init_pair(COLOR_BLACK, COLOR_BLACK, COLOR_BLACK);
            init_pair(COLOR_GREEN, COLOR_GREEN, COLOR_BLACK);
            init_pair(COLOR_WHITE, COLOR_WHITE, COLOR_BLACK);
            init_pair(COLOR_RED, COLOR_RED, COLOR_BLACK);
            init_pair(COLOR_CYAN, COLOR_CYAN, COLOR_BLACK);
            init_pair(COLOR_MAGENTA, COLOR_MAGENTA, COLOR_BLACK);
            init_pair(COLOR_BLUE, COLOR_BLUE, COLOR_BLACK);
            init_pair(COLOR_YELLOW, COLOR_YELLOW, COLOR_BLACK);
        }
    }

    while (1) {
        count++;
        if (count > 4) {
            count = 1;
        }

        if ((keypress = wgetch(stdscr)) != ERR) {
            if (screensaver == 1) {
                finish();
            } else {
                switch (keypress) {
                case 'q':
                    if (lock != 1) {
                        finish();
                    }
                    break;
                case 'a':
                    asynch = 1 - asynch;
                    break;
                case 'b':
                    bold = 1;
                    break;
                case 'B':
                    bold = 2;
                    break;
                case 'L':
                    lock = 1;
                    break;
                case 'n':
                    bold = 0;
                    break;
                case '0':
                case '1':
                case '2':
                case '3':
                case '4':
                case '5':
                case '6':
                case '7':
                case '8':
                case '9':
                    update = keypress - '0';
                    break;
                case '!':
                    mcolor = COLOR_RED;
                    rainbow = 0;
                    break;
                case '@':
                    mcolor = COLOR_GREEN;
                    rainbow = 0;
                    break;
                case '#':
                    mcolor = COLOR_YELLOW;
                    rainbow = 0;
                    break;
                case '$':
                    mcolor = COLOR_BLUE;
                    rainbow = 0;
                    break;
                case '%':
                    mcolor = COLOR_MAGENTA;
                    rainbow = 0;
                    break;
                case 'r':
                    rainbow = 1;
                    break;
                case 'm':
                    lambda = !lambda;
                    break;
                case '^':
                    mcolor = COLOR_CYAN;
                    rainbow = 0;
                    break;
                case '&':
                    mcolor = COLOR_WHITE;
                    rainbow = 0;
                    break;
                case 'p':
                case 'P':
                    pause = (pause == 0) ? 1 : 0;
                    break;
                }
            }
        }

        for (j = 0; j <= COLS - 1; j += 2) {
            if ((count > updates[j] || asynch == 0) && pause == 0) {
                if (oldstyle) {
                    /* Old style: shift the whole column down one cell and
                     * decide what enters at the top. */
                    for (i = LINES; i >= 1; i--) {
                        matrix[i][j].val = matrix[i - 1][j].val;
                    }
                    random = (int) rand() % (randnum + 8) + randmin;

                    if (matrix[1][j].val == 0) {
                        matrix[0][j].val = 1;
                    } else if (matrix[1][j].val == ' ' || matrix[1][j].val == -1) {
                        if (spaces[j] > 0) {
                            matrix[0][j].val = ' ';
                            spaces[j]--;
                        } else {
                            /* One in three streams gets a white head. */
                            if (((int) rand() % 3) == 1) {
                                matrix[0][j].val = 0;
                            } else {
                                matrix[0][j].val = (int) rand() % randnum + randmin;
                            }
                            spaces[j] = (int) rand() % LINES + 1;
                        }
                    } else if (random > highnum && matrix[1][j].val != 1) {
                        matrix[0][j].val = ' ';
                    } else {
                        matrix[0][j].val = (int) rand() % randnum + randmin;
                    }
                } else {
                    /* New style scrolling (default). */
                    if (matrix[0][j].val == -1 && matrix[1][j].val == ' ' && spaces[j] > 0) {
                        spaces[j]--;
                    } else if (matrix[0][j].val == -1 && matrix[1][j].val == ' ') {
                        length[j] = (int) rand() % (LINES - 3) + 3;
                        matrix[0][j].val = (int) rand() % randnum + randmin;
                        spaces[j] = (int) rand() % LINES + 1;
                    }
                    i = 0;
                    y = 0;
                    firstcoldone = 0;
                    while (i <= LINES) {
                        /* Skip over spaces */
                        while (i <= LINES && (matrix[i][j].val == ' ' || matrix[i][j].val == -1)) {
                            i++;
                        }
                        if (i > LINES) {
                            break;
                        }
                        /* Go to the head of this stream */
                        z = i;
                        y = 0;
                        while (i <= LINES && (matrix[i][j].val != ' ' && matrix[i][j].val != -1)) {
                            matrix[i][j].is_head = 0;
                            if (changes) {
                                if (rand() % 8 == 0) {
                                    matrix[i][j].val = (int) rand() % randnum + randmin;
                                }
                            }
                            i++;
                            y++;
                        }
                        if (i > LINES) {
                            matrix[z][j].val = ' ';
                            continue;
                        }
                        matrix[i][j].val = (int) rand() % randnum + randmin;
                        matrix[i][j].is_head = 1;

                        /* Once the stream reached its full length (or this is
                         * not the first stream in the column) start eating
                         * its tail so that it moves down. */
                        if (y > length[j] || firstcoldone) {
                            matrix[z][j].val = ' ';
                            matrix[0][j].val = -1;
                        }
                        firstcoldone = 1;
                        i++;
                    }
                }
            }

            /* Display this column */
            for (i = 1; i <= LINES; ++i) {
                move(i - 1, j);
