                    }
                    attroff(COLOR_PAIR(COLOR_WHITE));
                    if (bold) {
                        attroff(A_BOLD);
                    }
                    if (console || xwindow) {
                        attroff(A_ALTCHARSET);
                    }
                } else {
                    if (rainbow) {
                        int randomColor = rand() % 6;
                        switch (randomColor) {
                        case 0:
                            mcolor = COLOR_GREEN;
                            break;
                        case 1:
                            mcolor = COLOR_BLUE;
                            break;
                        case 2:
                            mcolor = COLOR_BLACK;
