import os, pty, sys, time, select, fcntl, termios, struct, signal
sys.path.insert(0, '/tmp/t')
from term import Term
def sample(cmd, keys=(), duration=1.0, rows=24, cols=80, env=None, interval=0.05, start_at=0.0):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ.pop('LC_CTYPE', None)
        if env: os.environ.update(env)
        os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    term = Term(rows, cols); snaps = []
    start = time.time(); keys = list(keys); nxt = start + max(interval, start_at); buf = b''
    while True:
        now = time.time()
        if keys and now - start >= keys[0][0]:
            os.write(fd, keys[0][1]); keys.pop(0)
        r,_,_ = select.select([fd], [], [], 0.002)
        if r:
            try: data = os.read(fd, 1 << 20)
            except OSError: break
            if not data: break
            buf += data
        if now >= nxt:
            # feed complete escape sequences only (keep a possibly partial trailing ESC sequence)
            cut = len(buf)
            k = buf.rfind(b'\x1b')
            if k >= 0 and k > len(buf) - 12 and not any(buf[k+1:].endswith(e) for e in ()):
                # if the last ESC sequence looks incomplete, hold it back
                tail = buf[k:]
                import re
                if not re.match(rb'\x1b(\[[0-9;?]*[A-Za-z@]|\([0B]|[=>MD78])', tail):
                    cut = k
            term.feed(buf[:cut]); buf = buf[cut:]
            snaps.append((now - start, [row[:] for row in term.cells]))
            nxt += interval
        if now - start > duration: break
    try: os.kill(pid, signal.SIGKILL)
    except Exception: pass
    os.waitpid(pid, 0)
    return snaps
